const upsertRecurrencePrice = `-- name: UpsertRecurrencePrice :exec
INSERT INTO recurrence_prices (recurrence_id, from_month, amount_cents)
VALUES (?, ?, ?)
ON CONFLICT (recurrence_id, from_month) DO UPDATE SET amount_cents = excluded.amount_cents
`

type UpsertRecurrencePriceParams struct {
	RecurrenceID int64
	FromMonth    string
	AmountCents  int64
}

func (q *Queries) UpsertRecurrencePrice(ctx context.Context, arg UpsertRecurrencePriceParams) error {
	_, err := q.db.ExecContext(ctx, upsertRecurrencePrice, arg.RecurrenceID, arg.FromMonth, arg.AmountCents)
	return err
}
